output_text:
[
  {
    "id": "pickup_entry_cart",
    "text": "A shopper should check in by taking the entry cart at the cart station before doing the shopping.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)"
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart_event"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items should not be carried by hand; a shopper must have a cart whenever taking shelf items.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_product_spots",
    "text": "Shelf-item pickup interactions are permitted only at recognized product pickup positions, not at arbitrary interaction cells.",
    "abstraction": {
      "state_properties": {
        "product_pickup_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(3,2)",
            "at(5,2)",
            "at(6,2)",
            "at(2,4)",
            "at(3,4)",
            "at(5,4)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "product_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "product_pickup_cell"
          }
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking the cart, the shopper must return it to the cart-return bay at cell (0,1) before the trip ends.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay_event": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_entry_cart_event",
      "discharge": "return_cart_to_bay_event"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper may put down the cart only in the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_without_cart",
    "text": "The shopper must leave the store on foot rather than exiting while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_cart_in_checkout_lane",
    "text": "Carts are not allowed in the bottom checkout corridor from cells (4,5) through (9,5).",
    "abstraction": {
      "state_properties": {
        "bottom_checkout_corridor": {
          "or": [
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_bottom_checkout_corridor": {
          "and": [
            "hasCart",
            "bottom_checkout_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_bottom_checkout_corridor"
    }
  },
  {
    "id": "no_cart_east_from_3_5",
    "text": "When pushing a cart at cell (3,5), the shopper must not continue east into the checkout corridor.",
    "abstraction": {
      "state_properties": {
        "cart_at_checkout_threshold": {
          "and": [
            "hasCart",
            "at(3,5)"
          ]
        }
      },
      "events": {
        "push_cart_east_from_threshold": {
          "pre": {
            "and": [
              "cart_at_checkout_threshold",
              "E"
            ]
          },
          "post": "at(4,5)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_from_threshold"
    }
  }
]
